// ============================================
// VALIDATION INPUT - Anthropic List Skills
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: api_key (BYOT pattern) ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string') {
  errors.push('api_key requis (BYOT pattern - aucun fallback sur env)');
}

// --- Optional: source filter ---
const validSources = ['all', 'anthropic', 'custom'];
let source = body.source || ctx.source || 'all';
if (!validSources.includes(source)) {
  source = 'all';
}

// --- Optional: betas ---
const betas = body.betas || ctx.betas || ['skills-2025-10-02'];

// --- Optional: metadata ---
const metadata = body.metadata || ctx.metadata || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    metadata: metadata
  };
}

return {
  valid: true,
  api_key: apiKey.trim(),
  source: source,
  betas: betas,
  metadata: metadata,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  metadata: input.metadata
};

// ============================================
// FORMAT RESPONSE - List Skills
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const latencyMs = Date.now() - (prevData.startTime || Date.now());

// Handle API error
if (input.error) {
  return {
    success: false,
    error: {
      code: input.error.type || 'ANTHROPIC_ERROR',
      message: input.error.message || 'Anthropic Skills API error',
      http_status: 500
    },
    metadata: prevData.metadata
  };
}

// Parse skills from response
const skills = (input.data || []).map(skill => ({
  id: skill.id,
  display_title: skill.display_title || skill.name || skill.id,
  description: skill.description || null,
  source: skill.source || 'anthropic',
  version: skill.version || 'latest',
  mime_types: skill.supported_mime_types || [],
  max_file_size_bytes: skill.max_file_size_bytes || null
}));

// Categorize skills
const anthropicSkills = skills.filter(s => s.source === 'anthropic');
const customSkills = skills.filter(s => s.source === 'custom');

return {
  success: true,
  skills: skills,
  summary: {
    total: skills.length,
    anthropic_count: anthropicSkills.length,
    custom_count: customSkills.length
  },
  filter: prevData.source,
  metadata: prevData.metadata,
  _trace: {
    latency_ms: latencyMs,
    api_version: '2023-06-01',
    beta: prevData.betas.join(',')
  }
};

